// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address currentOwner, address caller, address newOwner) public {
        vm.assume(newOwner != address(0));

        c.initialize();

        c.transferOwnership(currentOwner);

        assertTrue(c.owner() == currentOwner);

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == currentOwner));
    }
}
